2024-2025供暖季商河恒泰热源厂所有热泵的用气量分别是多少？.sql:
WITH start_period AS (SELECT pump_id, heatpump_total_gas AS start_data FROM (SELECT pump_id, heatpump_total_gas, data_time, ROW_NUMBER() OVER (PARTITION BY pump_id ORDER BY data_time ASC) AS rn FROM ods_sc01_ntjt_zhgr_heat_heatpump_inst_data WHERE pump_id IN ('1','2') AND data_time >= '2024-11-15 00:00:00') t WHERE rn = 1), 
    end_period AS (SELECT pump_id, heatpump_total_gas AS end_data FROM (SELECT pump_id, heatpump_total_gas, data_time, ROW_NUMBER() OVER (PARTITION BY pump_id ORDER BY data_time DESC) AS rn FROM ods_sc01_ntjt_zhgr_heat_heatpump_inst_data WHERE pump_id IN ('1','2') AND data_time <= '2025-03-15 00:00:00') t WHERE rn = 1) 
    SELECT s.pump_id, (e.end_data - s.start_data) AS total_data FROM start_period s JOIN end_period e ON s.pump_id = e.pump_id;
